import math

def countKReducibleNumbers(s: str, k: int) -> int:
    MOD = 10**9 + 7
    n_len = len(s)

    # Precompute combinations C(n, r)
    C = [[0] * (n_len + 1) for _ in range(n_len + 1)]
    for i in range(n_len + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD

    def get_popcount(num):
        return bin(num).count('1')

    # R[v] is the minimum steps to reach 1 from v.
    # We need enough range for popcounts of numbers up to n_len bits.
    # The maximum popcount is n_len (800).
    R = [0] * (n_len + 2)
    for i in range(2, n_len + 2):
        R[i] = 1 + R[get_popcount(i)]

    # A number x is k-reducible if it reaches 1 in <= k steps.
    # If x=1, it takes 0 steps.
    # If x > 1, it takes 1 + R[popcount(x)] steps.

    target_popcounts = []
    for p in range(1, n_len + 1):
        if p == 1:
            target_popcounts.append(p)
        else:
            # x is k-reducible if popcount(x) = p and R[p] <= k - 1
            if R[p] <= k - 1:
                target_popcounts.append(p)

    ans = 0
    current_pc = 0
    for i in range(n_len):
        bit = int(s[i])
        rem_bits = n_len - 1 - i
        if bit == 1:
            # If we change this '1' to a '0', the prefix is smaller than s.
            # Any combination of the remaining rem_bits can be chosen.
            for j in range(rem_bits + 1):
                total_pc = current_pc + j
                if total_pc > 0 and total_pc in target_popcounts:
                    ans = (ans + C[rem_bits][j]) % MOD
            current_pc += 1
        else:
            # Bit is '0', we must keep it as '0' to stay less than s.
            pass

    return ans
