def minLength(s: str, numOps: int) -> int:
    n = len(s)
    if n == 0:
        return 0
    if numOps >= n - 1:
        return 1

    def check_dp(L):
        # dp[i][j][c] is the minimum current run length ending at index i, 
        # using exactly j flips, where character at s[i] is c (0 or 1).
        inf = float('inf')
        # Using a 2D array to save memory/time: dp[j][c] for current index i
        # We use two layers for the DP to represent current and previous indices.
        dp = [[inf, inf] for _ in range(numOps + 1)]

        # Initial state for index 0
        for c in [0, 1]:
            cost = 1 if int(s[0]) != c else 0
            if cost <= numOps:
                dp[cost][c] = 1

        for i in range(1, n):
            new_dp = [[inf, inf] for _ in range(numOps + 1)]
            curr_orig = int(s[i])
            for j in range(numOps + 1):
                for prev_c in [0, 1]:
                    prev_val = dp[j][prev_c]
                    if prev_val == inf:
                        continue

                    # Option 1: Keep current character same as previous (curr_c == prev_c)
                    # This extends the run.
                    if prev_val + 1 <= L:
                        cost = 1 if curr_orig != prev_c else 0
                        nj = j + cost
                        if nj <= numOps:
                            new_dp[nj][prev_c] = min(new_dp[nj][prev_c], prev_val + 1)

                    # Option 2: Change current character to be different from previous (curr_c != prev_c)
                    # This starts a new run of length 1.
                    other_c = 1 - prev_c
                    cost = 1 if curr_orig != other_c else 0
                    nj = j + cost
                    if nj <= numOps:
                        new_dp[nj][other_c] = min(new_dp[nj][other_c], 1)
            dp = new_dp

        for j in range(numOps + 1):
            if dp[j][0] != inf or dp[j][1] != inf:
                return True
        return False

    low = 1
    high = n
    ans = n
    while low <= high:
        mid = (low + high) // 2
        if check_dp(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans

