def maxAmount(initialCurrency: str, pairs1: List[List[str]], rates1: List[float], 
               pairs2: List[List[str]], rates2: List[float]) -> float:
    """
    Conditions Checklist:
    1. Top-level function named `maxAmount`: Yes.
    2. Allowed modules only: Using typing (Yes).
    3. No forbidden calls (input, open, eval, exec, locals, globals, getattr): Yes.
    4. Return value instead of print: Yes.
    5. Handle Day 1 conversions (any number, including zero): Use Bellman-Ford/Floyd-Warshall approach for max path.
    6. Handle Day 2 conversions (any number, including zero): Same as above.
    7. Bidirectional rates: If A->B is r, then B->A is 1/r.
    8. Sequential logic: Day 1 first, then Day 2.
    9. Result: Maximum amount of initialCurrency at the end.
    """

    def get_max_rates(pairs: List[List[str]], rates: List[float]) -> dict:
        # Use a dictionary to represent the graph where adj[u][v] is the max rate from u to v
        adj = {}
        currencies = set()
        for i in range(len(pairs)):
            u, v = pairs[i]
            r = rates[i]
            currencies.add(u)
            currencies.add(v)
            if u not in adj: adj[u] = {}
            if v not in adj: adj[v] = {}

            # Update if a better rate is found (though constraints say no contradictions)
            adj[u][v] = max(adj[u].get(v, 0.0), r)
            adj[v][u] = max(adj[v].get(u, 0.0), 1.0 / r)

        # Floyd-Warshall to find all-pairs maximum rates
        dist = {u: {v: 0.0 for v in currencies} for u in currencies}
        for u in currencies:
            dist[u][u] = 1.0
            if u in adj:
                for v, r in adj[u].items():
                    dist[u][v] = max(dist[u][v], r)

        for k in currencies:
            for i in currencies:
                for j in currencies:
                    if dist[i][k] > 0 and dist[k][j] > 0:
                        dist[i][j] = max(dist[i][j], dist[i][k] * dist[k][j])
        return dist

    # Collect all unique currencies involved in either day to ensure the graph is complete
    all_currencies = {initialCurrency}
    for p in pairs1: 
        all_currencies.update(p)
    for p in pairs2: 
        all_currencies.update(p)

    # Get max conversion rates for Day 1 and Day 2
    dist1 = get_max_rates(pairs1, rates1)
    # Ensure all currencies are keys in dist1 even if not in pairs1
    for c in all_currencies:
        if c not in dist1:
