from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m = len(coins)
    n = len(coins[0])
    # dp[k][i][j] represents max coins at (i, j) with k neutralizations used.
    # Since we only need the previous row/column, we can optimize space to 3 x m x n or use a 3D array.
    # Given constraints (500x500), a full 3D array [3][m][n] is feasible.

    # Initialize DP table with very small value
    # dp[k][i][j] where k is number of neutralizations used (0, 1, or 2)
    dp = [[[-float('inf')] * n for _ in range(m)] for _ in range(3)]

    # Initial state at (0, 0)
    val = coins[0][0]
    if val >= 0:
        dp[0][0][0] = val
    else:
        dp[0][0][0] = val # Case where we don't neutralize a negative cell
        dp[1][0][0] = 0   # Case where we neutralize the negative cell at (0,0)

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            val = coins[i][j]
            for k in range(3):
                # Option 1: Don't neutralize current cell (only possible if val >= 0 or we choose to take the loss)
                # If val < 0, taking it is a valid move but reduces profit.
                prev_max = -float('inf')
                if i > 0: prev_max = max(prev_max, dp[k][i-1][j])
                if j > 0: prev_max = max(prev_max, dp[k][i][j-1])

                if prev_max != -float('inf'):
                    dp[k][i][j] = max(dp[k][i][j], prev_max + val)

                # Option 2: Neutralize current cell (only makes sense if val < 0 and k > 0)
                if val < 0 and k > 0:
                    prev_max_neutral = -float('inf')
                    if i > 0: prev_max_neutral = max(prev_max_neutral, dp[k-1][i-1][j])
                    if j > 0: prev_max_neutral = max(prev_max_neutral, dp[k-1][i][j-1])

                    if prev_max_neutral != -float('inf'):
                        dp[k][i][j] = max(dp[k][i][j], prev_max_neutral)

    return max(dp[0][m-1][n-1], dp[1][m-1][n-1], dp[2][m-1][n-1])
