def longestPalindrome(s: str, t: str) -> int:
    n, m = len(s), len(t)
    res = 0
    # Pre-calculate all possible palindromes from substrings of s and t
    # But since we need to concatenate s_sub + t_sub, 
    # let's iterate over all possible split points.

    # A substring is a palindrome if it equals its reverse.
    # The result can be:
    # 1. A palindrome entirely within s
    # 2. A palindrome entirely within t
    # 3. s_sub + t_sub forming a palindrome

    # Since constraints are tiny (30), we can just brute force all substrings.
    for i in range(n):
        for j in range(i, n + 1):
            sub_s = s[i:j]
            if sub_s == sub_s[::-1]:
                res = max(res, len(sub_s))

    for i in range(m):
        for j in range(i, m + 1):
            sub_t = t[i:j]
            if sub_t == sub_t[::-1]:
                res = max(res, len(sub_t))

    # Check all combinations of s_sub + t_sub
    for i in range(n + 1):
        for j in range(i, n + 1):
            s_part = s[i:j]
            for k in range(m + 1):
                for l in range(k, m + 1):
                    t_part = t[k:l]
                    combined = s_part + t_part
                    if combined == combined[::-1]:
                        res = max(res, len(combined))
    return res
