def longestPalindrome(s: str, t: str) -> int:
    max_len = 0
    # Generate all possible substrings of s (including empty)
    substrings_s = []
    for i in range(len(s) + 1):
        for j in range(i, len(s) + 1):
            substrings_s.append(s[i:j])

    # Generate all possible substrings of t (including empty)
    substrings_t = []
    for i in range(len(t) + 1):
        for j in range(i, len(t) + 1):
            substrings_t.append(t[i:j])

    # Check every combination of substring from s and substring from t
    for sub_s in substrings_s:
        for sub_t in substrings_t:
            combined = sub_s + sub_t
            if combined == combined[::-1]:
                max_len = max(max_len, len(combined))

    return max_len
