from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    # Sort events by timestamp. 
    # For same timestamp, process OFFLINE (type 0) before MESSAGE (type 1).
    processed_events = []
    for e in events:
        etype = 0 if e[0] == "OFFLINE" else 1
        processed_events.append((int(e[1]), etype, e))

    # Sort by timestamp first, then by type (OFFLINE before MESSAGE)
    processed_events.sort()

    mentions = [0] * numberOfUsers
    # offline_expiry maps user_id -> timestamp when they come back online
    offline_expiry = {}

    for _, etype, event in processed_events:
        timestamp = int(event[1])

        if etype == 0:  # OFFLINE
            # The third element is the user id string (e.g., "0")
            user_id_str = event[2]
            try:
                user_id = int(user_id_str)
            except ValueError:
                # Handle cases where it might be "id0" or just "0"
                user_id = int(user_id_str.replace("id", ""))
            offline_expiry[user_id] = timestamp + 60
        else:  # MESSAGE
            content = event[2]
            tokens = content.split()

            for token in tokens:
                if token == "ALL":
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif token == "HERE":
                    for i in range(numberOfUsers):
                        is_offline = (i in offline_expiry and offline_expiry[i] > timestamp)
                        if not is_offline:
                            mentions[i] += 1
                else:
                    # Handle tokens like "id0", "id1" etc.
                    if token.startswith("id"):
                        user_id = int(token[2:])
                        mentions[user_id] += 1
                    else:
                        # Fallback for raw numbers if they appear as IDs
                        try:
                            user_id = int(token)
                            mentions[user_id] += 1
                        except ValueError:
                            pass

    return mentions
